      "status": "MISSING",
      "chunk_id": null,
      "quote": null,
      "reason": "The evidence does not describe whether exclusions were distinguished based on outcomes not measured versus outcomes not reported."
    },
    {
      "element_id": "prisma_2020_5_e4",
      "status": "PARTIAL",
      "chunk_id": "text_9",
      "quote": "We prespecified subgroup exploration by age group, ERCP indication, procedure type, pancreatic duct manipulation or contrast injection, sphincterotomy, and operator or center volume.",
      "reason": "The evidence identifies subgroup categories explored in analyses, but it does not clearly state how groups used in each synthesis were defined and linked to the specific comparisons/objectives of the review."
    },
    {
      "element_id": "prisma_2020_5_e5",
      "status": "PARTIAL",
      "chunk_id": "text_6",
      "quote": "The search was limited to studies published between January 1, 2015, and June 26, 2025, to capture contemporary pediatric ERCP practice, including changes in therapeutic indications, endoscopic accessories, anesthesia support, and prophylaxis strategies.",
      "reason": "A rationale is provided for restricting the publication date range to capture contemporary practice. However, the evidence does not provide rationales for other notable eligibility restrictions."
    }
